def w(job, obj):
    p = f'/home/user/Possession-Taxonomy/rebuild/work/E4/shelves/{job}.json'
    t = p + '.tmp'; json.dump(obj, open(t, 'w'), ensure_ascii=False, indent=1); os.replace(t, p)
